  str_n23_level_name_11 = "N9 - Menyamar",
  str_n23_level_name_12 = "N10 - Kebenaran",
  str_n23_level_name_13 = "N11 - Keputusasaan",
  str_n23_level_name_14 = "N12 - Munculnya",
  str_n23_level_name_15 = "ST3 - Omong Kosong",
  str_n23_level_desc_1 = "-",
  str_n23_level_desc_2 = "Anda dan Wakil mencapai Rumah Berhantu Andersen dan menemukan bahwa pemiliknya adalah wajah yang familiar.",
  str_n23_level_desc_3 = "Di salah satu koridor, Anda bertemu sutradara film horor Jonny dan krunya. Anda segera menemukan identitas lain Minos ...",
  str_n23_level_desc_4 = "Sadie melepaskan diri dari Jonny dan mengejar Anda, membawa peta lokasi kru bersamanya.",
  str_n23_level_desc_5 = "Sosok misterius bertopeng memimpin gerombolan Eclipsites mengejar Anda. Sesuatu tentang semua ini sangat aneh...",
  str_n23_level_desc_6 = "Ruangan gelap, boneka menyeramkan, dan suara air menetes... Seseorang pasti telah merancang ini dengan sengaja... kan?",
  str_n23_level_desc_7 = "Saat jantungmu masih berdebar-debar karena ketakutan, cakar baja menjulur ke arahmu, mencoba memberitahumu sesuatu...",
  str_n23_level_desc_8 = "-",
  str_n23_level_desc_9 = "Anda merenungkan semua yang telah terjadi sejauh ini. Anda menyimpulkan bahwa... Tunggu, apakah ada orang di luar?",
  str_n23_level_desc_10 = "Anda semakin dekat dan dekat dengan kebenaran! Kirim musuh-musuh ini sebelum mereka mengganggu deduksi Anda!",
  str_n23_level_desc_11 = "Anda dan rekan Anda marah pada peristiwa yang terjadi malam ini. Seseorang harus bertanggung jawab atas segalanya, termasuk Eclipsites yang berdiri di hadapan Anda.",
  str_n23_level_desc_12 = "Lari, kabur. Dan apa pun yang Anda lakukan... jangan melihat ke belakang.",
  str_n23_level_desc_13 = "Buru-buru! Singkirkan sisa Eclipsites yang menghalangi jalanmu! Tunggu... Dimana Lilica dan Sadie?",
  str_n23_level_desc_14 = "Apa yang Anda takuti, hal yang tidak berani Anda hadapi, sekarang berdiri di depan Anda. Tidak ada pilihan lain selain bertarung sekarang.",
  str_n23_level_desc_15 = "-",
  str_n23_level_desc_long_1 = "Judul utama surat kabar Umbraton merinci seorang aktris tak dikenal yang hilang selama pembuatan film film horor dan menarik perhatian penuh Anda. Sementara itu, Vice telah terpaku pada grand opening Andersen Haunted House, yang mengklaim memiliki \"fenomena paranormal nyata.\" Dia mengundang Anda ke rumah berhantu, tetapi Anda tidak bisa melupakan hilangnya pikiran Anda.",
  str_n23_level_desc_long_2 = "Seperti yang diharapkan, rumah besar ini milik Nina Andersen. Minos mengikuti instruksi Nina untuk memandu Anda dan Wakil melalui tempat itu. Di dalam, Anda bertemu Lilica, sesama penggemar paranormal. Dia menyambut Anda dengan antusias dan sepertinya ingin mendokumentasikan petualangan ini dan mengubahnya menjadi sebuah film.",
  str_n23_level_desc_long_3 = "Anda bertemu sutradara dalam kasus aktris yang menghilang. Dia sudah memiliki rencana untuk film baru dan memperkenalkan Anda pada dua aktris, Goldie dan Sadie. Anda belajar dari percakapan bahwa Nina dan Minos tidak berada di halaman yang sama karena Jonny ingin syuting jangka panjang di mansion. Minos terjebak di tengah dan untuk sementara menjabat sebagai produser sementara.",
  str_n23_level_desc_long_4 = "Mengikuti bagan lokasi Sadie dan petunjuk Minos, Anda mencapai kamar tidur, lokasi pemotretan pertama. Anda menemukan televisi tua dengan gambar menyeramkan di layar. Percakapan singkat dengan orang bertopeng menunjukkan bahwa Anda tidak boleh meninggalkan rumah hantu itu hidup-hidup.",
  str_n23_level_desc_long_5 = "Meniup kuis, Anda tidak punya pilihan selain melawan sesama bertopeng dan Eclipsites, tetapi sesama bertopeng membatalkan serangan. Ternyata Nina ada di balik topeng, dan Eclipsites sebenarnya adalah teman dalam kostum. Nina bangga dengan \"daya tarik\" yang dipentaskannya. Kekasih paranormal Lilica membawa Wakil yang kecewa dan yang lainnya ke lokasi syuting berikutnya.",
  str_n23_level_desc_long_6 = "Lokasi kedua adalah showroom. Udara lembap dan boneka seram selalu mengingatkan bahwa rumah itu berhantu. Nyanyian lusuh dan suara gemericik air mulai bergema di sekitar area tersebut. Tapi saat Sadie mencemooh trik salon murah, air yang menetes tampaknya membuktikan bahwa dia salah.",
  str_n23_level_desc_long_7 = "Di luar ruang pamer, Anda bertemu dengan Mia, yang datang ke sini sendirian. Dia tampaknya menikmati tur sendirian, dan sebelum berpisah, dia secara samar menyampaikan peringatan yang mungkin hanya berlaku untuk dirinya sendiri: Hati-hati dan jangan biarkan \"dia\" menangkapmu.",
  str_n23_level_desc_long_8 = "Anda mengikuti Minos ke lokasi terakhir — ruang bawah tanah, di mana Anda melihat berbagai petunjuk aneh yang menyiratkan bahwa mantan pemilik telah menghukum anak-anak kecil. Selain itu, ada log kru film di dekatnya dengan konten yang mengganggu. Tiba-tiba, ruang bawah tanah menjadi gelap, dan Anda menyaksikan pemandangan menakutkan melalui ruang lingkup malam di kamera ... \nTapi ternyata bukan apa-apa; Anda paranoid tanpa alasan.",
  str_n23_level_desc_long_9 = "Setelah memeriksa semua lokasi syuting, Minos membawa Anda kembali ke kantor untuk memilah petunjuk. Anda setuju bahwa motif kru di balik hilangnya aktris adalah kuncinya. Tapi sedetik kemudian, Eclipsites mengepung kantor...",
  str_n23_level_desc_long_10 = "Setelah membuang Eclipsites, Anda kembali ke kantor. Minos mengobrak-abrik file untuk mencari lebih banyak petunjuk. Lilica membawa kembali foto-foto yang dikembangkan untuk menunjukkan kepada semua orang, hanya untuk membuat penemuan mengejutkan bahwa ada lengan di sana yang bukan milik siapa pun di ruangan itu.",
  str_n23_level_desc_long_11 = "Lilica mengungkapkan identitas aslinya sebagai pemeran utama wanita yang hilang dari film Jonny sebelumnya yang disebutkan dalam berita. Menghubungkan titik-titik, Anda mengetahui Jonny membuat film horor menggunakan Eclipsites, dan memutuskan untuk menghadapinya. Mengejutkan, Jonny bahkan lebih jahat dari yang Anda perkirakan dan membunuh Goldie sebelum mengalihkan perhatiannya ke Anda semua...",
  str_n23_level_desc_long_12 = "Direktur memberi tahu Anda bahwa dia membunuh setiap anggota kru sebelumnya kecuali Lilica, yang melarikan diri. Sekarang Anda tahu yang sebenarnya, Anda berikutnya. Lilica melihat seorang wanita aneh mendekat melalui kameranya, tapi tidak ada yang peduli. Mereka terlalu sibuk berlari.",
  str_n23_level_desc_long_13 = "Pertarungan berakhir dengan Lilica dan Sadie berpisah dari pesta dan bersembunyi di sebuah ruangan kecil bersama. Jonny memukul pintu dengan kapak sampai pecah, mendekati para wanita yang berteriak. Saat keadaan akan berubah menjadi yang terburuk, Jonny mendengar orang lain menelepon. Lalu dia tiba-tiba berbalik dan pergi...",
  str_n23_level_desc_long_14 = "Sebuah peti mati menghalangi jalan Anda. Suara kesemutan dari dalam peti mati menghentikan siapa pun yang mendekat. Jonny muncul di belakang Anda dan mulai syuting untuk klimaks film. Monster mengerikan merangkak keluar dari peti mati dan tidak ada tempat bagi Anda untuk lari ... Untungnya, Lilica dan Sadie tiba di tempat kejadian untuk melawan monster itu. Akhirnya, dengan bantuan dari Aurorian di rumah berhantu, Anda membunuh monster itu. Sutradara yang menyedihkan itu ingin memberi makan dirinya sendiri kepada monster itu, hanya agar Goldie muncul, masih hidup, dan mengakhiri leluconnya.",
  str_n23_level_desc_long_15 = [[
Semuanya berakhir dengan orang-orang Istvan membawa Jonny pergi, rekaman Lilica menjadi gangbuster, dan Rumah Hantu Andersen diuntungkan dari ketenaran yang baru ditemukan. Anda kembali beberapa hari kemudian untuk reuni, dengan Lilica, Sadie, dan Goldie menggembar-gemborkan aspirasi baru. 
Tapi suara samar air yang menetes tiba-tiba terdengar di kejauhan ...]]
